        private static void Require(byte[] buf, int offset, int size)
        {
            if (buf == null)
            {
                throw new ArgumentNullException(nameof(buf));
            }
            if (offset < 0 || offset > buf.Length)
            {
                throw new ArgumentOutOfRangeException(nameof(offset));
            }
            if (buf.Length - offset < size)
            {
                throw new ArgumentException("ClassyMcClassface: need " + size + " bytes, have " + (buf.Length - offset), nameof(buf));
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PutLE16(byte[] buf, int offset, ushort value)
        {
#if SKYWIRE_SPAN
            System.Buffers.Binary.BinaryPrimitives.WriteUInt16LittleEndian(new Span<byte>(buf, offset, 2), value);
#else
            buf[offset] = unchecked((byte)value);
            buf[offset + 1] = unchecked((byte)(value >> 8));
#endif
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static ushort GetLE16(byte[] buf, int offset)
        {
#if SKYWIRE_SPAN
            return System.Buffers.Binary.BinaryPrimitives.ReadUInt16LittleEndian(new ReadOnlySpan<byte>(buf, offset, 2));
#else
            return unchecked((ushort)(buf[offset] | buf[offset + 1] << 8));
#endif
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PutBE16(byte[] buf, int offset, ushort value)
        {
#if SKYWIRE_SPAN
            System.Buffers.Binary.BinaryPrimitives.WriteUInt16BigEndian(new Span<byte>(buf, offset, 2), value);
#else
            buf[offset] = unchecked((byte)(value >> 8));
            buf[offset + 1] = unchecked((byte)value);
#endif
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static ushort GetBE16(byte[] buf, int offset)
        {
#if SKYWIRE_SPAN
            return System.Buffers.Binary.BinaryPrimitives.ReadUInt16BigEndian(new ReadOnlySpan<byte>(buf, offset, 2));
#else
            return unchecked((ushort)(buf[offset] << 8 | buf[offset + 1]));
#endif
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PutLE32(byte[] buf, int offset, uint value)
        {
#if SKYWIRE_SPAN
            System.Buffers.Binary.BinaryPrimitives.WriteUInt32LittleEndian(new Span<byte>(buf, offset, 4), value);
#else
            buf[offset] = unchecked((byte)value);
            buf[offset + 1] = unchecked((byte)(value >> 8));
            buf[offset + 2] = unchecked((byte)(value >> 16));
            buf[offset + 3] = unchecked((byte)(value >> 24));
#endif
