        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static uint GetLE32(byte[] buf, int offset)
        {
#if SKYWIRE_SPAN
            return System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(new ReadOnlySpan<byte>(buf, offset, 4));
#else
            return buf[offset] | (uint)buf[offset + 1] << 8 | (uint)buf[offset + 2] << 16 | (uint)buf[offset + 3] << 24;
#endif
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
