        {
#if SKYWIRE_SPAN
            System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(new Span<byte>(buf, offset, 4), value);
#else
            buf[offset] = unchecked((byte)(value >> 24));
            buf[offset + 1] = unchecked((byte)(value >> 16));
            buf[offset + 2] = unchecked((byte)(value >> 8));
            buf[offset + 3] = unchecked((byte)value);
