        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static uint GetBE32(byte[] buf, int offset)
        {
#if SKYWIRE_SPAN
            return System.Buffers.Binary.BinaryPrimitives.ReadUInt32BigEndian(new ReadOnlySpan<byte>(buf, offset, 4));
#else
            return (uint)buf[offset] << 24 | (uint)buf[offset + 1] << 16 | (uint)buf[offset + 2] << 8 | buf[offset + 3];
