        // Native byte order: BitConverter.IsLittleEndian is a constant to the JIT.
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private static void PutNE32(byte[] buf, int offset, uint value)
        {
            if (BitConverter.IsLittleEndian)
            {
                PutLE32(buf, offset, value);
            }
            else
